+    LocalTensor<float> combinedB = base[hiddenDimCeil];
+    LocalTensor<float> xRes = base[hiddenDimCeil * 2];
+    LocalTensor<float> work = base[hiddenDimCeil * 3];
+    LocalTensor<float> castStage = base[hiddenDimCeil * 4];
+    LocalTensor<float> storeStage = base[hiddenDimCeil * 5];
+
+    int64_t lastBatch = -1;
+    // 与 StoreFull 中 MTE3->V 复用 storeStage/work 的栅栏配对，循环前预置一次。
+    SetFlag<HardEvent::MTE3_V>(eventIdMte3ToV);
+    for (int64_t rowIdx = rowStart; rowIdx < rowEnd; rowIdx++) {
+        // 等待上一行写出对 storeStage/work 的占用释放，再复用这些缓冲。
+        WaitFlag<HardEvent::MTE3_V>(eventIdMte3ToV);
+        int64_t batch = rowIdx / seqLen;
+        if (batch != lastBatch) {
+            // combinedW = weight * (1 + scale)
+            LoadFull(work, scaleGm, batch * hiddenDim, castStage);
+            Adds(work, work, ONE_FLOAT, hiddenDim);
+            PipeBarrier<PIPE_V>();
+            if (hasWeight) {
+                LoadFull(xRes, weightGm, 0, castStage);
+                Mul(combinedW, xRes, work, hiddenDim);
+            } else {
+                Adds(combinedW, work, 0.0f, hiddenDim);
+            }
+            PipeBarrier<PIPE_V>();
+            // combinedB = bias * (1 + scale) + shift
+            if (hasBias) {
+                LoadFull(xRes, biasGm, 0, castStage);
+                Mul(xRes, xRes, work, hiddenDim);
+                PipeBarrier<PIPE_V>();
+                LoadFull(combinedB, shiftGm, batch * hiddenDim, castStage);
+                Add(combinedB, combinedB, xRes, hiddenDim);
+            } else {
+                LoadFull(combinedB, shiftGm, batch * hiddenDim, castStage);
+            }
+            PipeBarrier<PIPE_V>();
+            lastBatch = batch;
+        }
+
+        LoadFull(xRes, xGm, rowIdx * hiddenDim, castStage);
+        // mean
+        Muls(work, xRes, aveFactor, hiddenDim);
+        PipeBarrier<PIPE_V>();
+        ReduceSum(reduceFloat, work, work, hiddenDim);
+        SetFlag<HardEvent::V_S>(eventIdVToS);
+        WaitFlag<HardEvent::V_S>(eventIdVToS);
+        float meanValue = reduceFloat.GetValue(0);
+        // var
+        Adds(work, xRes, -meanValue, hiddenDim);
+        PipeBarrier<PIPE_V>();
+        Mul(xRes, work, work, hiddenDim);
+        PipeBarrier<PIPE_V>();
+        ReduceSum(reduceFloat, xRes, xRes, hiddenDim);
+        SetFlag<HardEvent::V_S>(eventIdVToS);
+        WaitFlag<HardEvent::V_S>(eventIdVToS);
+        float rstdValue = ONE_FLOAT / sqrt(reduceFloat.GetValue(0) * aveFactor + epsilon);
+        // normalize + 融合调制
+        Muls(work, work, rstdValue, hiddenDim);
+        PipeBarrier<PIPE_V>();
+        Mul(work, work, combinedW, hiddenDim);
+        PipeBarrier<PIPE_V>();
+        Add(work, work, combinedB, hiddenDim);
+        PipeBarrier<PIPE_V>();
+        StoreFull(rowIdx * hiddenDim, work, storeStage);
+        SetFlag<HardEvent::MTE3_V>(eventIdMte3ToV);
+    }
+    WaitFlag<HardEvent::MTE3_V>(eventIdMte3ToV);
+}
