if ((args_.aType != ge::DT_FLOAT16 && args_.aType != ge::DT_BF16) ||
    (args_.bType != ge::DT_FLOAT16 && args_.bType != ge::DT_BF16)) {
    OP_LOGI(args_.opName, "Input only supports fp16/bf16, skip ScSplitK+AL1FullLoad template");
    return false;
}
```

